var baseUri = ResolveSupportedServiceUri(_foundryManager);
if (baseUri is not { IsAbsoluteUri: true })
{
    Logger.LogError("[FoundryClient] No usable Foundry Local service URI was discovered");
    return null;
}
return baseUri;

var serviceUri = await _foundryClient.GetRequiredServiceUriAsync().ConfigureAwait(false);
if (serviceUri is null)
    throw new InvalidOperationException("Foundry Local service endpoint is unavailable.");
_serviceUrl = serviceUri.ToString().TrimEnd('/');
